import React from 'react';
import { DEFAULT_VIEW3D_SETTINGS, type View3DSettings } from './view3dTypes';
import {
  DimensionsSection,
    WallsSection,
      DoorsSection,
        WindowsSection,
          CorniceSection,
            FenceSection,
              ViewScopeSection,
                 StreetsSection,
                   BalconyLightSection,
                } from './View3DSettingsSections';
                interface Props {
                  settings: View3DSettings;
                    onChange: (settings: View3DSettings) => void;
                      onUpdateFloorOverride?: (floor: number, patch: Partial<View3DSettings>) => void;
                        onClearFloorOverride?: (floor: number) => void;
                          maxFloor?: number;
                            onClose: () => void;
                            }
                            export const View3DSettingsDialog: React.FC<Props> = ({
                              settings,
                                onChange,
                                  onUpdateFloorOverride,
                                    onClearFloorOverride,
                                      maxFloor = 0,
                                        onClose,
                                        }) => {
                                          const hasOverride = (fl: number): boolean => {
                                              const o = settings?.floorOverrides?.[fl];
                                                  return !!o && Object.keys(o).length > 0;
                                                    };
                                                      const [editingTarget, setEditingTarget] = React.useState<'global' | number>('global');
                                                        const displayedSettings: View3DSettings = React.useMemo(() => {
                                                            if (editingTarget === 'global') return settings;
                                                                const override = settings?.floorOverrides?.[editingTarget];
                                                                    if (!override) return settings;
                                                                        return { ...settings, ...override, floorOverrides: settings.floorOverrides };
                                                                          }, [settings, editingTarget]);
                                                                            const update = (patch: Partial<View3DSettings>) => {
                                                                                if (editingTarget === 'global') {
                                                                                      onChange({ ...settings, ...patch });
                                                                                          } else if (onUpdateFloorOverride) {
                                                                                                onUpdateFloorOverride(editingTarget, patch);
                                                                                                    }
                                                                                                      };
                                                                                                        const handleReset = () => {
                                                                                                            if (editingTarget === 'global') {
                                                                                                                  if (confirm('هل تريد إعادة الإعدادات العامة إلى القيم الافتراضية؟\n(لن تتأثر تجاوزات الأدوار)')) {
                                                                                                                          onChange({ ...DEFAULT_VIEW3D_SETTINGS, floorOverrides: settings.floorOverrides });
                                                                                                                                }
                                                                                                                                    } else if (onClearFloorOverride) {
                                                                                                                                          if (confirm(`هل تريد إزالة تجاوزات الدور ${editingTarget}؟\n(سيعود لوراثة الإعدادات العامة)`)) {
                                                                                                                                                  onClearFloorOverride(editingTarget);
                                                                                                                                                        }
                                                                                                                                                            }
                                                                                                                                                              };
                                                                                                                                                                const sectionProps = { settings: displayedSettings, update };
                                                                                                                                                                  const safeMax = Number.isFinite(maxFloor) ? maxFloor : 0;
                                                                                                                                                                    return (
                                                                                                                                                                        <div style={overlayStyle}>
                                                                                                                                                                              <div style={dialogStyle}>
                                                                                                                                                                                      <div style={topBarStyle}>
                                                                                                                                                                                                <button onClick={onClose} title="إغلاق" style={closeBtnStyle}>
                                                                                                                                                                                                            ✕
                                                                                                                                                                                                                      </button>
                                                                                                                                                                                                                                <span style={titleStyle}>⚙️ إعدادات المنظور</span>
                                                                                                                                                                                                                                          <button onClick={handleReset} title="إعادة للافتراضي" style={resetBtnStyle}>
                                                                                                                                                                                                                                                      🔄 افتراضي
                                                                                                                                                                                                                                                                </button>
                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                <div style={floorSelectorStyle}>
                                                                                                                                                                                                                                                                                          <label style={floorSelectorLabelStyle}>
                                                                                                                                                                                                                                                                                                      🎯 الدور المُعدَّل:
                                                                                                                                                                                                                                                                                                                </label>
                                                                                                                                                                                                                                                                                                                          <select
                                                                                                                                                                                                                                                                                                                                      value={editingTarget === 'global' ? 'global' : String(editingTarget)}
                                                                                                                                                                                                                                                                                                                                                  onChange={(e) => {
                                                                                                                                                                                                                                                                                                                                                                const v = e.target.value;
                                                                                                                                                                                                                                                                                                                                                                              setEditingTarget(v === 'global' ? 'global' : parseInt(v, 10));
                                                                                                                                                                                                                                                                                                                                                                                          }}
                                                                                                                                                                                                                                                                                                                                                                                                      style={floorSelectInputStyle}
                                                                                                                                                                                                                                                                                                                                                                                                                >
                                                                                                                                                                                                                                                                                                                                                                                                                            <option value="global">⚙️ عام (افتراضي لكل الأدوار)</option>
                                                                                                                                                                                                                                                                                                                                                                                                                                        {Array.from({ length: safeMax + 1 }).map((_, f) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                      <option key={f} value={String(f)}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {`🏢 الدور ${f}`}{hasOverride(f) ? ' 🔵' : ''}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </option>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </select>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    {editingTarget !== 'global' && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div style={floorHintStyle}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {hasOverride(editingTarget)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ? '🔵 هذا الدور له إعدادات خاصة'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              : '⬇️ يورث من الإعدادات العامة — أي تعديل سيُنشئ إعدادات خاصة لهذا الدور'}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <DimensionsSection {...sectionProps} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <ViewScopeSection {...sectionProps} maxFloor={safeMax} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <WallsSection {...sectionProps} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <DoorsSection {...sectionProps} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <WindowsSection {...sectionProps} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <CorniceSection {...sectionProps} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <FenceSection {...sectionProps} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <StreetsSection {...sectionProps} />
                                                                                                                                                                                                                   <BalconyLightSection {...sectionProps} />                                                                                                                                                                                                                                                                                                                                                                                                                                                                 <div style={{ height: 20 }} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // ============================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // الأنماط
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // ============================================================
